# app/systems/accounting/services/closing/entry_writer.rb
module Accounting
  module Closing
    # Writes and removes the system entries of a fiscal year's closing (the
    # temporary closing, ending and beginning entries).
    module EntryWriter
      SYSTEM_CONTEXT = Starter::SYSTEM_CONTEXT

      module_function

      # Saves an approved entry generated by closing `fiscal_year`.
      #   description_kind  key of its description (entry_descriptions.*)
      #   lines             line hashes, in order
      #   line_kind         line template kind, or a callable taking a line
      #   attributes        entry_type, date and any other entry attribute
      #                     (fiscal_year defaults to the year being closed)
      def create!(fiscal_year, member:, description_kind:, lines:, line_kind:, **attributes)
        entry = Accounting::JournalEntry.new(
          organization: fiscal_year.organization, fiscal_year: fiscal_year, state: :approved, source: fiscal_year,
          creator: member, approved_by: member, approved_at: Time.current, system_context: SYSTEM_CONTEXT,
          **attributes
        )
        entry.write_attribute(:description, description(fiscal_year, description_kind))
        descriptions = LineDescriptions.new(fiscal_year).preload(lines)
        lines.each_with_index do |line, index|
          kind = line_kind.respond_to?(:call) ? line_kind.call(line) : line_kind
          entry.items.build(line.merge(row: index + 1))
               .write_attribute(:description, descriptions.describe(kind, line, date: entry.date))
        end
        return entry if entry.save

        raise Error.new(:entry_invalid, messages: entry.errors.full_messages)
      end

      # Deletes the entries of a type generated by closing `fiscal_year`.
      def destroy_entries!(fiscal_year, entry_type)
        fiscal_year.closing_entries.where(entry_type: entry_type).find_each do |entry|
          entry.system_context = SYSTEM_CONTEXT
          next if entry.destroy

          raise Error.new(:entry_not_removable, messages: entry.errors.full_messages)
        end
      end

      # { locale => text }, with the fiscal year's name in each locale.
      def description(fiscal_year, kind)
        fiscal_year.organization.entry_locales.to_h do |locale|
          name = Mobility.with_locale(locale) { fiscal_year.name.to_s }
          [ locale, Accounting::FiscalYearClosing.model_t("entry_descriptions.#{kind}", fiscal_year: name, locale: locale) ]
        end
      end
    end
  end
end
